+<script>
+(()=>{'use strict';
+const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d'),$=id=>document.getElementById(id);
+const ui={menu:$('menu'),over:$('gameOver'),coin:$('coinCount'),fuel:$('fuelFill'),fuelT:$('fuelText'),hp:$('healthFill'),hpT:$('healthText'),dist:$('distanceText'),mode:$('modeText'),tag:$('weatherTag'),toast:$('toast'),compass:$('compass'),compassText:$('compassText'),note:$('footerNote')};
