+function start(){initAudio();selectedMode=document.querySelector('.mode.selected').dataset.mode;running=true;dead=false;world=0;score=0;fuel=100;hp=100;carX=0;steer=0;speed=0;spawnClock=.5;entities=[];particles=[];checkpoint=0;checkpointAt=0;runCoins=0;activeBiome=biomeFor(bestDist);ui.menu.classList.add('hidden');ui.over.classList.add('hidden');ui.mode.textContent=modes[selectedMode];ui.tag.textContent=selectedMode==='weather'?'WHITEOUT ACTIVE':biomes[activeBiome].weather;ui.compass.classList.toggle('show',selectedMode==='compass');ui.note.textContent=selectedMode==='compass'?'FOLLOW THE BEARING · FIND THE MARKER':'A / D OR ← → TO STEER';updateHud()}
