+function initAudio(){if(!sfxOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume()}catch{}}
+function tone(freq,duration,type='sine',volume=.045,slide=0){if(!sfxOn)return;initAudio();if(!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,freq+slide),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
+function say(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.5}
+function rand(a,b){return a+Math.random()*(b-a)}
+function spawn(){let r=Math.random(),type=r<.26?'coin':r<.39?'fuel':r<.67?'rock':'mud';if(fuel<42&&Math.random()<.42)type='fuel';entities.push({type,x:[-.64,0,.64][Math.floor(Math.random()*3)],z:1,spin:rand(0,6.2),hit:false})}
+function particlesAt(x,y,color,n=12){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-100,100),vy:rand(-130,55),life:rand(.35,.8),max:.8,color,size:rand(2,5)})}
+function collect(e){e.hit=true;if(e.type==='coin'){runCoins++;score+=.015;tone(820,.11,'sine',.04,380);say('+1 TRAIL COIN')}else if(e.type==='fuel'){fuel=Math.min(100,fuel+29);tone(460,.18,'triangle',.06,350);say('FUEL +29%')}else{const damage=e.type==='rock'?25:15;hp=Math.max(0,hp-damage);speed*=.47;shake=10;particlesAt(W*(.5+carX*.24),H*.8,e.type==='rock'?'#d8c29a':'#70543b',18);tone(100,.22,'sawtooth',.09,-50);say(e.type==='rock'?'ROCK IMPACT · HP -25':'DEEP MUD · HP -15');if(hp<=0)finish('hp')}}
+function update(dt){if(!running)return;const weather=selectedMode==='weather';const steering=(keys.right?1:0)-(keys.left?1:0);steer+=(steering-steer)*Math.min(1,dt*8);const traction=1+saved.tires*.1;carX+=steer*dt*(1.4+speed*.018)/traction;carX=Math.max(-.89,Math.min(.89,carX));const target=25+saved.engine*2;speed+=(target-speed)*dt*(selectedMode==='weather'?.36:.75);if(speed<8)speed=8;world+=speed*dt*.03;score+=speed*dt*.0017;fuel-=dt*(.31+speed*.012)*(1+saved.engine*.035);if(fuel<=0){fuel=0;updateHud();finish('fuel');return}
+activeBiome=biomeFor(Math.max(bestDist,score));ui.tag.textContent=weather?'WHITEOUT ACTIVE':biomes[activeBiome].weather;
+spawnClock-=dt;if(spawnClock<=0){spawn();spawnClock=rand(.65,1.3)*(100/(speed+35))+.28}
+for(const e of entities){e.z-=dt*(.36+speed*.0055);e.spin+=dt*3;if(!e.hit&&e.z<.18&&e.z>-.04&&Math.abs(e.x-carX)<.30){if(e.type==='rock'||e.type==='mud')collect(e);else collect(e)}}entities=entities.filter(e=>e.z>-.11&&!e.hit);
+if(selectedMode==='compass'){checkpointAt+=dt*(.36+speed*.0055);const bearing=Math.round(Math.abs(carX)*90+((Math.floor(score*11)*37)%170));ui.compassText.textContent=(carX<0?'W':'E')+' '+String(bearing).padStart(3,'0');if(score>=2.2){finish('checkpoint');return}}
+for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=210*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);shake=Math.max(0,shake-dt*28);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}updateHud();if(score>bestDist)bestDist=score}
+function roadBounds(y){const horizon=H*.25;let t=Math.max(0,Math.min(1,(y-horizon)/(H-horizon)));const half=W*(.105+.32*t);const center=W*.5+Math.sin(world*.22)*W*.025*t;return [center-half,center+half,center]}
+function poly(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill()}
+function drawBackground(time){const biome=biomes[activeBiome],weather=selectedMode==='weather';let sky=ctx.createLinearGradient(0,0,0,H*.5);sky.addColorStop(0,activeBiome===2?'#91b5bd':activeBiome===1?'#e4955f':'#81a99b');sky.addColorStop(1,activeBiome===2?'#d9e7df':activeBiome===1?'#f0c17f':'#c6c79a');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);ctx.fillStyle=activeBiome===1?'#ffe0a2':'#f5e9bb';ctx.globalAlpha=.78;ctx.beginPath();ctx.arc(W*.76,H*.15,Math.min(W,H)*.055,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
+// distant ridge silhouettes
+for(let layer=0;layer<3;layer++){ctx.fillStyle=activeBiome===2?['#78959b','#647c7c','#536966'][layer]:activeBiome===1?['#c77d51','#a96348','#795347'][layer]:['#77917a','#55745d','#3a5b4b'][layer];ctx.beginPath();ctx.moveTo(0,H*.34);for(let x=0;x<=W+40;x+=40){const y=H*(.2+layer*.045)+Math.sin(x*.012+layer*2+world*.07)*H*.035+Math.cos(x*.023+layer)*H*.018;ctx.lineTo(x,y)}ctx.lineTo(W,H*.45);ctx.lineTo(0,H*.45);ctx.fill()}
+ctx.fillStyle=biome.color;ctx.fillRect(0,H*.35,W,H*.65);
+// stylized roadside trees/rocks, scrolling toward player
+for(let i=0;i<17;i++){const z=((i/17+world*.095)%1),y=H*(.28+z*.74),scale=.22+z*.9;const sway=Math.sin(i*12+world*.1)*W*.018;const side=i%2?-1:1;const x=W*.5+side*(W*(.18+z*.34))+sway;if(activeBiome===1){poly([[x-12*scale,y],[x,y-24*scale],[x+15*scale,y]],'#9a5d40');ctx.fillStyle='#473b34';ctx.fillRect(x-2*scale,y-4*scale,4*scale,7*scale)}else if(activeBiome===2){poly([[x-19*scale,y],[x,y-35*scale],[x+19*scale,y]],'#f0f1df');poly([[x-13*scale,y-10*scale],[x,y-35*scale],[x+10*scale,y-10*scale]],'#708984')}else{ctx.fillStyle='#654e3a';ctx.fillRect(x-2*scale,y-9*scale,4*scale,12*scale);poly([[x-18*scale,y-5*scale],[x,y-34*scale],[x+18*scale,y-5*scale]],'#26483c');poly([[x-14*scale,y-14*scale],[x,y-39*scale],[x+14*scale,y-14*scale]],'#315744')}}
+// road
+const horizon=H*.29,[lTop,rTop]=roadBounds(horizon),[lBot,rBot]=roadBounds(H*1.08);poly([[lTop,horizon],[rTop,horizon],[rBot,H*1.08],[lBot,H*1.08]],biome.road);const [lo1,ro1]=roadBounds(H*.54),[lo2,ro2]=roadBounds(H*.80);poly([[lTop,horizon],[lo1,H*.54],[lo2,H*.80],[lBot,H*1.08]],'#eee2c24a');poly([[rTop,horizon],[ro1,H*.54],[ro2,H*.80],[rBot,H*1.08]],'#eee2c24a');
+// broken center markings
+for(let i=0;i<9;i++){let z=((i/9+world*.32)%1),y=horizon+z*(H-horizon),y2=y+Math.max(3,z*25),b=roadBounds(y),b2=roadBounds(y2),x=b[2],x2=b2[2],w=Math.max(1,z*5);poly([[x-w,y],[x+w,y],[x2+w,y2],[x2-w,y2]],'#e9e3ca'+(z>.15?'b8':'50'))}
+// road edge glints
+const baseY=H*.6;for(let i=0;i<13;i++){const z=((i/13+world*.46)%1),y=horizon+z*(H-horizon),[l,r]=roadBounds(y),sz=Math.max(1,z*3);ctx.fillStyle=i%2?'#e2a761':'#f1e4c4';ctx.fillRect(l-sz*2,y,sz*2,sz);ctx.fillRect(r,y,sz*2,sz)}
+if(weather){const fade=ctx.createLinearGradient(0,0,0,H);fade.addColorStop(0,'#e1e2d844');fade.addColorStop(.55,'#c4d2ce66');fade.addColorStop(1,'#c4d2ce0a');ctx.fillStyle=fade;ctx.fillRect(0,0,W,H);ctx.fillStyle='#eef4f1';for(let i=0;i<55;i++){let x=(i*173+time*(30+(i%5)*9))%(W+20),y=(i*97+time*(90+(i%4)*20))%H;ctx.globalAlpha=.2+(i%3)*.1;ctx.fillRect(x,y,1.4,6+(i%4)*3)}ctx.globalAlpha=1}}

input.newString:
if(weather){const fade=ctx.createLinearGradient(0,0,0,H);fade.addColorStop(0,'#e1e2d844');fade.addColorStop(.55,'#c4d2ce66');fade.addColorStop(1,'#c4d2ce0a');ctx.fillStyle=fade;ctx.fillRect(0,0,W,H);ctx.fillStyle='#eef4f1';for(let i=0;i<55;i++){let x=(i*173+time*(30+(i%5)*9))%(W+20),y=(i*97+time*(90+(i%4)*20))%H;ctx.globalAlpha=.2+(i%3)*.1;ctx.fillRect(x,y,1.4,6+(i%4)*3)}ctx.globalAlpha=1}}
function drawEntity(e){const z=Math.max(0,Math.min(1,e.z)),y=H*(.29+(1-z)*.72),[l,r,c]=roadBounds(y),x=c+e.x*(r-l)*.34,scale=.24+(1-z)*1.2;ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.rotate(e.type==='coin'?Math.sin(e.spin)*.13:0);
if(e.type==='coin'){ctx.shadowColor='#f6d766';ctx.shadowBlur=14;ctx.fillStyle='#e7b848';ctx.beginPath();ctx.ellipse(0,-9,8,11,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff0a3';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#fff2ac';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText('✦',0,-6)}else if(e.type==='fuel'){ctx.shadowColor='#88dd96';ctx.shadowBlur=10;ctx.fillStyle='#d9e8ca';ctx.fillRect(-8,-20,16,19);ctx.fillStyle='#ef7652';ctx.fillRect(-6,-17,12,11);ctx.fillStyle='#d9e8ca';ctx.fillRect(-3,-24,7,5);ctx.fillStyle='#fff';ctx.fillRect(-2,-14,4,6)}else if(e.type==='rock'){poly([[-14,-3],[-11,-17],[-2,-23],[10,-18],[15,-4],[7,0]],'#827e70');poly([[-8,-15],[-2,-21],[5,-17],[-1,-14]],'#aaa493');ctx.fillStyle='#544f49';ctx.fillRect(-12,-4,25,4)}else{ctx.fillStyle='#6c5038';ctx.beginPath();ctx.ellipse(0,-5,18,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#876342';ctx.beginPath();ctx.ellipse(-5,-7,7,3,0,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawCar(){const [l,r,c]=roadBounds(H*.84),x=c+carX*(r-l)*.38,y=H*.81;ctx.save();ctx.translate(x,y);ctx.rotate(-steer*.09);const s=Math.min(1,W/430);ctx.scale(s,s);ctx.shadowColor='#07100d';ctx.shadowBlur=18;ctx.shadowOffsetY=9;ctx.fillStyle='#111915';ctx.fillRect(-25,-38,8,19);ctx.fillRect(17,-38,8,19);ctx.fillRect(-25,13,8,19);ctx.fillRect(17,13,8,19);ctx.shadowBlur=0;ctx.shadowOffsetY=0;
// rally body
ctx.fillStyle='#e7e5d3';ctx.beginPath();ctx.moveTo(-20,-39);ctx.lineTo(17,-39);ctx.lineTo(23,-27);ctx.lineTo(25,23);ctx.lineTo(18,34);ctx.lineTo(-18,34);ctx.lineTo(-25,23);ctx.lineTo(-23,-27);ctx.closePath();ctx.fill();ctx.fillStyle='#c94f35';ctx.fillRect(-24,-8,48,13);ctx.fillStyle='#ece6d0';ctx.fillRect(-18,-31,36,17);ctx.fillStyle='#35555a';ctx.beginPath();ctx.moveTo(-15,-29);ctx.lineTo(15,-29);ctx.lineTo(12,-17);ctx.lineTo(-12,-17);ctx.closePath();ctx.fill();ctx.fillStyle='#243b40';ctx.fillRect(-13,10,26,12);ctx.fillStyle='#f9e2a8';ctx.fillRect(-18,27,9,4);ctx.fillRect(9,27,9,4);ctx.fillStyle='#e8f4e3';ctx.fillRect(-20,-34,6,4);ctx.fillRect(14,-34,6,4);ctx.fillStyle='#fff';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText('47',0,2);ctx.restore();
}
function draw(time){ctx.setTransform(DPR,0,0,DPR,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));drawBackground(time);entities.forEach(drawEntity);drawCar();for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.restore();if(selectedMode==='weather'&&running){const v=ctx.createRadialGradient(W/2,H*.7,Math.min(W,H)*.1,W/2,H*.7,Math.max(W,H)*.72);v.addColorStop(0,'transparent');v.addColorStop(1,'#d7e6df33');ctx.fillStyle=v;ctx.fillRect(0,0,W,H)}}
