[['leftBtn','left'],['rightBtn','right']].forEach(([id,dir])=>{const b=$(id);b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);setDirection(dir,true)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>setDirection(dir,false)))});
document.querySelectorAll('.mode').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.mode').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')}));$('startBtn').addEventListener('click',start);$('restartBtn').addEventListener('click',()=>{ui.over.classList.add('hidden');ui.menu.classList.remove('hidden');updateGarage()});$('soundBtn').addEventListener('click',()=>{sfxOn=!sfxOn;$('soundBtn').textContent=sfxOn?'♫':'♪';if(sfxOn)initAudio()});
document.querySelectorAll('.upgrade').forEach(btn=>btn.addEventListener('click',()=>{const key=btn.dataset.upgrade,cost={engine:80+saved.engine*65,tires:70+saved.tires*60,suspension:90+saved.suspension*65}[key];if(saved.coins>=cost&&saved[key]<5){saved.coins-=cost;saved[key]++;tone(520,.16,'triangle',.05,260);save();updateGarage();say(key.toUpperCase()+' UPGRADED')}}));
updateGarage();updateHud();
})();
</script></main></body></html>

